package mx.com.mesaregia.ordenes.mapper; import mx.com.mesaregia.ordenes.api.response.*; import mx.com.mesaregia.ordenes.domain.entity.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class OrdenMapper {
 public OrdenListItemResponse list(OrdenServicio o){return new OrdenListItemResponse(o.getId(),o.getFolio(),o.getEstado(),o.getTipoCompromiso(),o.getIdCotizacionExterno(),o.getIdCotizacionVersionExterno(),o.getIdClienteProspectoExterno(),o.getClienteSnapshot(),o.getContactoSnapshot(),o.getEventoSnapshot(),o.getFechaHoraEventoSnapshot(),o.getFechaGeneracion(),o.getVersion());}
 public OrdenDetalleResponse det(OrdenDetalle d){return new OrdenDetalleResponse(d.getId(),d.getDetallePadre()==null?null:d.getDetallePadre().getId(),d.getTipoConcepto(),d.getIdConceptoExterno(),d.getCodigoSnapshot(),d.getNombreSnapshot(),d.getCantidad(),d.getOrdenVisual());}
 public HistorialOrdenResponse hist(HistorialEstadoOrden h){return new HistorialOrdenResponse(h.getId(),h.getEstadoAnterior(),h.getEstadoNuevo(),h.getAccion(),h.getMotivo(),h.getFechaHora(),h.getIdUsuarioExterno());}
 public OrdenResponse full(OrdenServicio o,List<OrdenDetalle> d,List<HistorialEstadoOrden> h){return new OrdenResponse(o.getId(),o.getFolio(),o.getEstado(),o.getTipoCompromiso(),o.getIdCotizacionExterno(),o.getIdCotizacionVersionExterno(),o.getIdClienteProspectoExterno(),o.getClienteSnapshot(),o.getContactoSnapshot(),o.getEventoSnapshot(),o.getFechaHoraEventoSnapshot(),o.getDomicilioEventoSnapshot(),o.getObservaciones(),o.getReferenciaPagoExterna(),o.getReferenciaReservaExterna(),o.getFechaGeneracion(),o.getActualizadoEn(),o.getVersion(),d.stream().map(this::det).toList(),h.stream().map(this::hist).toList());}
}
